1	using System.Diagnostics;
2	using TutorFlow.Core.Autorizacion;
3	using TutorFlow.Core.Conocimiento;
4	
5	namespace TutorFlow.Core.Asistente;
6	
7	public sealed record PreguntaEntrada(string Pregunta, Usuario Usuario);
