79	    public async Task<ResultadoPregunta> EjecutarAsync(
80	        PreguntaEntrada entrada,
81	        string ipOrigen,
82	        string correlationId,
83	        CancellationToken cancellationToken)
84	    {
85	        var presupuestoApi = TimeSpan.FromSeconds(_limites.PresupuestoApiAcademicaSegundos);
86	        var sesion = new SesionPregunta(entrada, ipOrigen, correlationId, new ApiAcademicaConPresupuesto(_apiAcademica, presupuestoApi));
87	        sesion.Directorio = await ConstructorDirectorio.ConstruirAsync(entrada.Usuario, sesion.Api, _configuracion.CodigosAsignatura, cancellationToken);
88	        var decision = Autorizar(sesion);
89	        if (!decision.Permitido)
90	        {
91	            return Denegar(sesion, decision.Motivo, 0);
92	        }
93	
94	        return _presupuesto.Agotado
95	            ? NoDisponible(sesion, ResultadoAuditoria.Error)
96	            : await ResponderAsync(sesion, cancellationToken);
97	    }
98	
99	    private DecisionAcceso Autorizar(SesionPregunta sesion)
100	    {
101	        if (sesion.Directorio is not { } directorio)
102	        {
103	            return DecisionAcceso.Denegar(MotivoDenegacion.IdentidadInvalida);
104	        }
105	
106	        var identidad = _politicaAcceso.EvaluarIdentidad(sesion.Entrada.Usuario, directorio);
107	        return identidad.Permitido
108	            ? _politicaAcceso.EvaluarPregunta(sesion.Entrada.Usuario, sesion.Entrada.Pregunta, directorio)
109	            : identidad;
110	    }
111	
112	    private async Task<ResultadoPregunta> ResponderAsync(SesionPregunta sesion, CancellationToken cancellationToken)
113	    {
114	        var directorio = sesion.Directorio!;
115	        var secciones = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(sesion.Entrada.Pregunta), _limites.MaximoSeccionesRecuperadas);
116	        var conversacion = new ConversacionLlm(_clienteLlm, new HerramientasAsistente(sesion.Api, _politicaAcceso), _limites, _configuracion);
117	        var contexto = new ContextoUsuario(sesion.Entrada.Usuario, directorio);
118	        var resultado = await conversacion.EjecutarAsync(contexto, sesion.Entrada.Pregunta, secciones, sesion.Registro, cancellationToken);
119	        sesion.Uso = resultado.Uso;
120	        _presupuesto.Registrar(CalculadoraCosto.Calcular(resultado.Uso, _configuracion.Precio));
121	        return resultado.Estado switch
122	        {
123	            EstadoConversacion.IdAjeno => Denegar(sesion, MotivoDenegacion.HerramientaIdAjeno, resultado.Uso.Total),
124	            EstadoConversacion.LimiteHerramientas => NoDisponible(sesion, ResultadoAuditoria.LimiteHerramientas),
125	            EstadoConversacion.Rechazada => Responder(sesion, Textos.NoVerificable, [], ResultadoAuditoria.Error),
126	            _ => Completar(sesion, resultado.Texto ?? string.Empty, secciones)
127	        };
128	    }
129	
130	    private ResultadoPregunta Completar(SesionPregunta sesion, string texto, IReadOnlyList<SeccionDocumento> secciones)
131	    {
132	        if (texto.Trim() == Textos.SinInformacion)
133	        {
134	            return Responder(sesion, Textos.SinInformacion, [], ResultadoAuditoria.SinInformacion, usoDatos: false);
135	        }
136	
137	        var fundamentos = _baseConocimiento.BuscarSecciones(ConsultaDeRecuperacion.DeTexto(texto), _limites.MaximoSeccionesRecuperadas);
138	        foreach (var seccion in secciones.Concat(fundamentos))
139	        {
140	            sesion.Registro.AgregarFuente($"{seccion.Titulo}. {seccion.Texto}");
141	        }
142	
143	        var directorio = sesion.Directorio!;
144	        var autorizados = _politicaAcceso.IdsPersonasAutorizadas(sesion.Entrada.Usuario, directorio);
145	        var candidatas = ElegirCitasNormativas(texto, fundamentos, secciones);
146	        var verificada = _verificadorSalida.Verificar(sesion.Entrada.Usuario, texto, candidatas, autorizados, sesion.Registro.Fuentes, _baseConocimiento, directorio);
147	        return Responder(sesion, verificada.Respuesta, CitasFinales(sesion, verificada), verificada.Resultado);
148	    }
149	
150	    private IReadOnlyList<Cita> CitasFinales(SesionPregunta sesion, SalidaVerificada verificada)
151	    {
152	        if (verificada.Resultado != ResultadoAuditoria.Respondida)
153	        {
154	            return verificada.Citas;
155	        }
156	
157	        var reglas = _verificadorSalida.DescartarCitasInexistentes(sesion.Registro.Reglas, _baseConocimiento);
158	        return [.. verificada.Citas.Concat(reglas).Concat(sesion.Registro.Citas).Distinct()];
159	    }
160	
161	    private IReadOnlyList<Cita> ElegirCitasNormativas(string texto, IReadOnlyList<SeccionDocumento> fundamentos, IReadOnlyList<SeccionDocumento> secciones)
162	    {
163	        var explicitas = _verificadorSalida.DescartarCitasInexistentes(ExtractorCitas.De(texto), _baseConocimiento);
164	        return explicitas.Count > 0
165	            ? explicitas
166	            : [.. fundamentos.Concat(secciones).Select(s => new Cita(s.Documento, s.Seccion)).Distinct()];
167	    }
168	
169	    private ResultadoPregunta Responder(
170	        SesionPregunta sesion,
171	        string texto,
172	        IReadOnlyList<Cita> citas,
173	        ResultadoAuditoria resultado,
174	        bool? usoDatos = null)
175	    {
176	        var respuesta = new RespuestaAsistente(
177	            texto,
178	            citas,
179	            usoDatos ?? sesion.Registro.UsoDatos,
180	            sesion.Uso.Total,
181	            CalculadoraCosto.Calcular(sesion.Uso, _configuracion.Precio));
182	        Auditar(sesion, resultado, null, citas);
183	        return new ResultadoPregunta(TipoResultadoPregunta.Respondida, respuesta, resultado, null);
184	    }
185	
186	    private ResultadoPregunta Denegar(SesionPregunta sesion, MotivoDenegacion? motivo, int tokens)
187	    {
188	        var costo = CalculadoraCosto.Calcular(sesion.Uso, _configuracion.Precio);
189	        var citas = new[] { Textos.CitaNegativa() };
190	        var respuesta = new RespuestaAsistente(Textos.Negativa(sesion.Entrada.Usuario.Rol), citas, false, tokens, costo);
191	        Auditar(sesion, ResultadoAuditoria.Denegada, motivo, citas);
192	        return new ResultadoPregunta(TipoResultadoPregunta.Denegada, respuesta, ResultadoAuditoria.Denegada, motivo);
193	    }
194	
195	    private ResultadoPregunta NoDisponible(SesionPregunta sesion, ResultadoAuditoria resultado)
196	    {
197	        Auditar(sesion, resultado, null, []);
198	        return new ResultadoPregunta(TipoResultadoPregunta.NoDisponible, null, resultado, null);
199	    }
200	
201	    private void Auditar(SesionPregunta sesion, ResultadoAuditoria resultado, MotivoDenegacion? motivo, IReadOnlyList<Cita> citas)
202	    {
203	        var usuario = sesion.Entrada.Usuario;
204	        _auditor.Registrar(new EventoAuditoria(
205	            _auditor.AhoraUtc,
206	            sesion.CorrelationId,
207	            sesion.IpOrigen,
208	            usuario.Rol,
209	            usuario.Id,
210	            AuditorPeticiones.SanearPregunta(usuario, sesion.Entrada.Pregunta, sesion.Directorio ?? ConstructorDirectorio.Vacio),
211	            resultado,
212	            motivo,
213	            sesion.Registro.Estudiantes,
214	            sesion.Registro.Recursos,
215	            citas,
216	            sesion.Uso.Total,
217	            CalculadoraCosto.Calcular(sesion.Uso, _configuracion.Precio),
218	            sesion.Cronometro.ElapsedMilliseconds,
219	            _configuracion.Precio is null));
220	    }
221	
222	    private sealed class SesionPregunta(PreguntaEntrada entrada, string ipOrigen, string correlationId, ApiAcademicaConPresupuesto api)
223	    {
224	        public PreguntaEntrada Entrada { get; } = entrada;
225	
226	        public string IpOrigen { get; } = ipOrigen;
227	
228	        public string CorrelationId { get; } = correlationId;
229	
230	        public ApiAcademicaConPresupuesto Api { get; } = api;
231	
232	        public Stopwatch Cronometro { get; } = Stopwatch.StartNew();
233	
234	        public RegistroConsultas Registro { get; } = new();
235	
236	        public DirectorioAcademico? Directorio { get; set; }
237	
238	        public UsoTokens Uso { get; set; } = new(0, 0);
239	    }
240	}
