144	    private async Task<ResultadoHerramienta> ConsultarPrograma(SolicitudHerramienta solicitud)
145	    {
146	        var programas = _politicaAcceso.ProgramasAutorizados(solicitud.Contexto.Usuario, solicitud.Contexto.Directorio);
147	        if (programas.Count == 0)
148	        {
149	            return ResultadoHerramienta.Texto("No tienes programas asignados, por lo que no hay datos de estudiantes para consultar.");
150	        }
151	
152	        var bloques = new List<string>();
153	        var resumenes = new List<ResumenEstudiante>();
154	        foreach (var programa in solicitud.Contexto.Directorio.Programas.Where(p => programas.Contains(p.Id)))
155	        {
156	            bloques.Add(await DescribirProgramaAsync(solicitud, programa, resumenes));
157	        }
158	
159	        solicitud.Registro.RegistrarReglas(ReglasAplicadas.DePrograma(resumenes));
160	        return ResultadoHerramienta.Texto(string.Join("\n\n", bloques));
